(7031258, 1067486, 40391, '<td valign="top">Lovely.</td>', 'Lovely.', '2013-05-03 00:31:45.000000', NULL, 1),
(7031259, 1066576, 136989, '<td valign="top">Oh my gosh!  She''s so adorable.  I love that you caught her running and the contrast with the snow is beautiful.  I just hope it isn''t your cat making her run like that. :)</td>', 'Oh my gosh!  She''s so adorable.  I love that you caught her running and the contrast with the snow is beautiful.  I just hope it isn''t your cat making her run like that. :)', '2013-05-03 00:32:16.000000', NULL, 1),
(7031261, 1067287, 40391, '<td valign="top">Wonderful lighting!</td>', 'Wonderful lighting!', '2013-05-03 00:34:38.000000', NULL, 1),
(7031262, 1067029, 136989, '<td valign="top">The crop is a bit too tall to me for the proportion of the flower and vase.  But great concept and lovely lighting.  I like the feel that the b/w adds.</td>', 'The crop is a bit too tall to me for the proportion of the flower and vase.  But great concept and lovely lighting.  I like the feel that the b/w adds.', '2013-05-03 00:36:05.000000', NULL, 1),
