(7032404, 1067110, 63218, '<td valign="top">I almost laughed out loud from delighted surprise! This is awesome. I can''t figure out how you did it but I love it all. Nice, nice title.</td>', 'I almost laughed out loud from delighted surprise! This is awesome. I can''t figure out how you did it but I love it all. Nice, nice title.', '2013-05-05 18:37:26.000000', NULL, 1),
(7032406, 1067584, 63218, '<td valign="top">Wow, it''s hard to be this cool every day. What a strange, odd, idiosyncratic image--the illustration of ''serendippity.'' It puts me in a hammock, or a canoe, or on the dock. I like it here. The title is wonderful. Instant fav.</td>', 'Wow, it''s hard to be this cool every day. What a strange, odd, idiosyncratic image--the illustration of ''serendippity.'' It puts me in a hammock, or a canoe, or on the dock. I like it here. The title is wonderful. Instant fav.', '2013-05-05 18:43:39.000000', NULL, 1),
(7032407, 1067466, 63218, '<td valign="top">I saw the black one first. The noise works very well in this for me, adding mystery &amp; whimsy. Instant fav.</td>', 'I saw the black one first. The noise works very well in this for me, adding mystery & whimsy. Instant fav.', '2013-05-05 18:45:21.000000', NULL, 1),
