INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7032495, 1067407, 43463, '<td valign="top">Voted earlier coming back to comment. <br/> <br/>I like that the objects you chose for this still life arrangement are all forms of ''tech'' that have become outdated in the march to ''better'' and improved technology (wrist watches will/are go(ing) that way too since now most just check their cell phone/Iphone for the time). The B&amp;W tones and details are fabulous. The image grain is just the right amount without being heavy handed in giving that feel of age and times past. Not sure the off kilter pyramid arrangement works best for this still life.</td>', 'Voted earlier coming back to comment.  I like that the objects you chose for this still life arrangement are all forms of ''tech'' that have become outdated in the march to ''better'' and improved technology (wrist watches will/are go(ing) that way too since now most just check their cell phone/Iphone for the time). The B&W tones and details are fabulous. The image grain is just the right amount without being heavy handed in giving that feel of age and times past. Not sure the off kilter pyramid arrangement works best for this still life.', '2013-05-05 22:21:29.000000', NULL, 1),
(7032496, 1067250, 100831, '<td valign="top">Excellent seeing.. like a puppet stage or something.</td>', 'Excellent seeing.. like a puppet stage or something.', '2013-05-05 22:21:51.000000', NULL, 1),
(7032497, 1066855, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>I really like the composition with empty glasses acting as leading lines that draws the eye to the end of the bar with the waiting bottle off in the distance. Great details and lighting on the glasses. Image grain is well done as well giving it just the right amount of nostalgic feel/mood.</td>', 'Voted earlier coming back to comment. I really like the composition with empty glasses acting as leading lines that draws the eye to the end of the bar with the waiting bottle off in the distance. Great details and lighting on the glasses. Image grain is well done as well giving it just the right amount of nostalgic feel/mood.', '2013-05-05 22:24:49.000000', NULL, 1),
(7032501, 1067164, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Awww, what a sleepy dog! He looks like he is standing guard but he/she is so desperately tired the eyes have just drooped down and closed for a snooze:-) Lighting and B&amp;W tones are great. The only critique I have is that I think the image grain is a wee bit too heavy-handed - especially where it peppers the woman in the backdrop. The grain there is too much that it appears like a crackled pattern. Pull back on the grain and make it subtle - I think that way will make it look better visually.</td>', 'Voted earlier coming back to comment. Awww, what a sleepy dog! He looks like he is standing guard but he/she is so desperately tired the eyes have just drooped down and closed for a snooze:-) Lighting and B&W tones are great. The only critique I have is that I think the image grain is a wee bit too heavy-handed - especially where it peppers the woman in the backdrop. The grain there is too much that it appears like a crackled pattern. Pull back on the grain and make it subtle - I think that way will make it look better visually.', '2013-05-05 22:35:05.000000', NULL, 1),
(7032504, 1066172, 100831, '<td valign="top">it seems so final. Grain to ashes. well done.</td>', 'it seems so final. Grain to ashes. well done.', '2013-05-05 22:44:38.000000', NULL, 1),
